type Section = "inicio" | "agenda" | "clientes" | "servicos" | "questionarios" | "financeiro" | "gestao";

const roleLabel: Record<string, string> = {
  admin: "Gestor(a)", recepcao: "Recepção", profissional: "Profissional", cliente: "Cliente", user: "Cliente",
};

const statusLabel: Record<string, string> = {
  PENDENTE: "Solicitado", AGUARDANDO_CONFIRMACAO: "Aguardando confirmação", CONFIRMADA: "Confirmada",
  EM_ATENDIMENTO: "Em atendimento", CONCLUIDA: "Realizada", CANCELADA: "Cancelada",
  NAO_COMPARECEU: "Falta", BLOQUEADA: "Bloqueada", ABERTA: "Em aberto", PAGA: "Paga",
};

function currency(value: string | number | null | undefined) {
  return new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(Number(value ?? 0));
}

function dateTime(value: Date | string | null | undefined) {
  if (!value) return "—";
  return new Date(value).toLocaleString("pt-BR", { dateStyle: "short", timeStyle: "short" });
}

function dateOnly(value: Date | string | null | undefined) {
  if (!value) return "—";
  return new Date(value).toLocaleDateString("pt-BR");
}

function exportCommissionReport(rows: Array<{ profissionalNome: string; percentual: string; valor: string; status: string }>) {
  const reportWindow = window.open("", "_blank", "width=900,height=720");
  if (!reportWindow) { toast.error("Permita a abertura de janelas para salvar o relatório em PDF."); return; }
  const escapeHtml = (value: string) => value.replace(/[&<>'"]/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" }[char] ?? char));
  const total = rows.reduce((sum, row) => sum + Number(row.valor), 0);
  reportWindow.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Relatório de comissões — Aura</title><style>body{font-family:Arial,sans-serif;color:#2c2627;margin:40px}h1{font-family:Georgia,serif;margin:0;color:#8f3156}p{color:#6d6264}table{border-collapse:collapse;width:100%;margin-top:28px}th,td{padding:12px;border-bottom:1px solid #eadfe2;text-align:left}th{color:#8f3156;text-transform:uppercase;font-size:11px;letter-spacing:.08em}.total{margin-top:24px;font-size:18px;font-weight:700;text-align:right}@media print{body{margin:22px}}</style></head><body><p>AURA GESTÃO ESTÉTICA</p><h1>Relatório de comissões</h1><p>Emitido em ${new Date().toLocaleString("pt-BR")}</p><table><thead><tr><th>Profissional</th><th>Percentual</th><th>Status</th><th>Valor</th></tr></thead><tbody>${rows.map((row) => `<tr><td>${escapeHtml(row.profissionalNome)}</td><td>${escapeHtml(String(row.percentual))}%</td><td>${escapeHtml(row.status)}</td><td>${currency(row.valor)}</td></tr>`).join("") || "<tr><td colspan='4'>Não há comissões para o período.</td></tr>"}</tbody></table><p class="total">Total: ${currency(total)}</p></body></html>`);
  reportWindow.document.close();
  reportWindow.focus();
  window.setTimeout(() => reportWindow.print(), 150);
}

function StatusBadge({ value }: { value: string }) {
  const className = value === "CONCLUIDA" || value === "PAGA" || value === "CONFIRMADA"
    ? "status-success" : value === "CANCELADA" || value === "NAO_COMPARECEU" ? "status-danger" : "status-neutral";
  return <span className={`status-badge ${className}`}>{statusLabel[value] ?? value}</span>;
}

function SectionHeader({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) {
  return <div className="section-header">
    <div>
      <p className="eyebrow">{eyebrow}</p>
      <h1>{title}</h1>
      <p className="section-description">{description}</p>
    </div>
    {action}
  </div>;
}

function EmptyRow({ cols, message }: { cols: number; message: string }) {
  return <TableRow><TableCell colSpan={cols} className="h-28 text-center text-muted-foreground">{message}</TableCell></TableRow>;
}

function readFileAsDataUrl(file: File) {
  return new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("Não foi possível ler a imagem."));
    reader.onload = () => resolve(String(reader.result));
    reader.readAsDataURL(file);
  });
}

