      <div className="sidebar-brand"><div className="brand-mark"><Sparkles /></div><div><strong>Aura</strong><span>Gestão estética</span></div><Button variant="ghost" size="icon" className="mobile-close" onClick={() => setMobileMenu(false)}><X /></Button></div>
