      <div className="sidebar-footer"><div className="profile-card"><span className="profile-initial">{user.name?.slice(0, 1).toUpperCase() ?? "A"}</span><div><strong>{user.name ?? "Usuário"}</strong><span>{roleLabel[role]}</span></div></div><Button variant="ghost" size="sm" onClick={() => logout()} className="logout-action"><LogOut /> Sair</Button></div>
